diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..c09a682 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -170,6 +170,83 @@ assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: t
 assert.equal(profiles.evaluateModelProof(local, { model: 'other-model', trusted: true }).status, 'failed');
 assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: false }).status, 'unknown');

+// Adversarial model substitution: the adapter ran a cheaper model than the
+// profile requested and reported it honestly under a verified receipt. The
+// substitution must read as failed -- never passed, never unknown -- and the
+// telemetry the adapter never sent must stay unknown instead of defaulting.
+const substituted = Object.freeze({
+  schema_version: 1,
+  branch_id: profiles.branchIdForProfile(local),
+  runtime: local.runtime,
+  model: 'qwen3-coder:7b',
+  trusted: true,
+  cost: null,
+  duration_ms: null,
+  tokens: null,
+  source: 'codex-jsonl',
+  branch_result_digest: `sha256:${'e'.repeat(64)}`,
+});
+assert.deepEqual(profiles.evaluateModelProof(local, substituted), {
+  requested_model: local.model,
+  observed_model: 'qwen3-coder:7b',
+  status: 'failed',
+  reason_code: 'MODEL_OBSERVATION_MISMATCH',
+});
+const verified = { status: 'verified', reason_code: 'FORK_RECEIPT_VERIFIED' };
+const substitutedState = profiles.missionControlExecutorState({
+  profile: local, observation: substituted, wrapper, verification: verified,
+});
+assert.equal(substitutedState.requested_model, local.model);
+assert.equal(substitutedState.observed_model, 'qwen3-coder:7b');
+assert.equal(substitutedState.model_status, 'failed');
+assert.equal(substitutedState.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+// A verified receipt binds the branch; it never launders the substituted model.
+assert.equal(substitutedState.receipt_status, 'verified');
+for (const [value, status] of [
+  [substitutedState.cost, substitutedState.cost_status],
+  [substitutedState.duration_ms, substitutedState.duration_status],
+  [substitutedState.tokens, substitutedState.tokens_status],
+]) {
+  assert.equal(value, null);
+  assert.equal(status, 'unknown');
+}
+// Telemetry that is present but malformed is missing telemetry, not evidence.
+const malformedState = profiles.missionControlExecutorState({
+  profile: local,
+  observation: {
+    ...copy(substituted),
+    cost: { amount: 3, unit: 'USD', source: 'codex-jsonl' },
+    duration_ms: '120',
+    tokens: -1,
+  },
+  wrapper,
+  verification: verified,
+});
+assert.equal(malformedState.model_status, 'failed');
+assert.deepEqual(
+  [malformedState.cost_status, malformedState.duration_status, malformedState.tokens_status],
+  ['unknown', 'unknown', 'unknown'],
+);
+// The public replay reports the same failure and leaks nothing new.
+const substitutedReplay = profiles.publicExecutorReplay({
+  profile: local, observation: substituted, wrapper, verification: verified,
+});
+assert.equal(substitutedReplay.requested_model, local.model);
+assert.equal(substitutedReplay.observed_model, 'qwen3-coder:7b');
+assert.equal(substitutedReplay.model_status, 'failed');
+assert.equal(substitutedReplay.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.deepEqual(
+  [substitutedReplay.cost_status, substitutedReplay.duration_status, substitutedReplay.tokens_status],
+  ['unknown', 'unknown', 'unknown'],
+);
+// An unverified substitution is unknown, and a path-like model is never echoed.
+assert.deepEqual(profiles.evaluateModelProof(local, { ...copy(substituted), trusted: false }), {
+  requested_model: local.model, observed_model: null, status: 'unknown', reason_code: 'MODEL_OBSERVATION_UNTRUSTED',
+});
+assert.deepEqual(profiles.evaluateModelProof(local, { ...copy(substituted), model: '../../secret-model' }), {
+  requested_model: local.model, observed_model: null, status: 'unknown', reason_code: 'MODEL_OBSERVATION_UNPARSABLE',
+});
+
 const missionUnknown = profiles.missionControlExecutorState({ profile: local, observation: null, wrapper: null });
 assert.equal(missionUnknown.requested_model, local.model);
 assert.equal(missionUnknown.observed_model, null);
